() => {
  // Find elements with opacity < 1
  const all = document.querySelectorAll('*');
  const hidden = [];
  for (const el of all) {
    const cs = getComputedStyle(el);
    const op = parseFloat(cs.opacity);
    if (op < 0.5 && el.offsetParent !== null) {
      hidden.push({
        tag: el.tagName,
        text: (el.textContent ?? "").slice(0, 60),
        opacity: cs.opacity,
        transform: cs.transform.slice(0, 80),
        hasAnimateProp: el.hasAttribute('data-framer-component-type') || (el.className?.toString?.() ?? "").includes('motion'),
        classes: (el.className?.toString?.() ?? "").slice(0, 80),
      });
    }
  }
  return {
    bodyClasses: document.body.className,
    totalHidden: hidden.length,
    samples: hidden.slice(0, 10),
    motionDetected: !!document.querySelector('[style*="opacity"]'),
  };
}

() => {
  // Force cesoir-reduced-motion override to see what happens
  document.body.classList.add('cesoir-reduced-motion');
  // Give the page a moment to recompute
  return { bodyClasses: document.body.className };
}

() => {
  // Check what matchMedia says
  const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
  return { matches: mq.matches, media: mq.media };
}

() => {
  // Find the first motion.section with variants hero ~ the profile hero
  const hero = document.querySelector('section[class*="px-6"]');
  if (!hero) return { error: 'no hero' };
  const cs = getComputedStyle(hero);
  const firstChild = hero.firstElementChild;
  const firstChildCs = firstChild ? getComputedStyle(firstChild) : null;
  return {
    hero: { opacity: cs.opacity, transform: cs.transform.slice(0, 80), transition: cs.transition.slice(0, 100) },
    firstChild: firstChildCs ? { tag: firstChild.tagName, opacity: firstChildCs.opacity, transform: firstChildCs.transform.slice(0, 80) } : null,
  };
}

() => {
  // Monkey-patch matchMedia to return reduced-motion=true, then reload the motion components
  const originalMatchMedia = window.matchMedia;
  window.matchMedia = (query) => {
    const result = originalMatchMedia(query);
    if (query.includes('prefers-reduced-motion')) {
      return {
        matches: true,
        media: query,
        addListener: result.addListener?.bind(result),
        removeListener: result.removeListener?.bind(result),
        addEventListener: result.addEventListener?.bind(result),
        removeEventListener: result.removeEventListener?.bind(result),
        dispatchEvent: () => true,
        onchange: null,
      };
    }
    return result;
  };
  // Check effect
  return { now: window.matchMedia('(prefers-reduced-motion: reduce)').matches };
}

() => {
  // Inspect: what's the state of motion children?
  // The monkey-patch was lost on reload, so reduced-motion is FALSE again
  const results = [];
  document.querySelectorAll('section, h1, h2, button').forEach((el, i) => {
    if (i > 15) return;
    const cs = getComputedStyle(el);
    results.push({
      tag: el.tagName,
      text: (el.textContent ?? '').slice(0, 40),
      opacity: cs.opacity,
      visibility: cs.visibility,
      display: cs.display,
      transform: cs.transform.slice(0, 60),
    });
  });
  return {
    prefersReducedMotion: window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    bodyClasses: document.body.className,
    samples: results,
  };
}

